import sys
from collections import defaultdict, deque

def main():
    import sys
    input = sys.stdin.read().splitlines()
    idx = 0
    results = []
    while idx < len(input):
        t = int(input[idx])
        idx += 1
        for _ in range(t):
            n, m = map(int, input[idx].split())
            idx += 1
            graph = defaultdict(list)
            in_degree = [0] * (n + 1)
            for _ in range(m):
                a, b = map(int, input[idx].split())
                graph[a].append(b)
                in_degree[b] += 1
                idx += 1
            dp = [0] * (n + 1)
            dp[1] = 1
            queue = deque([1])
            visited = [False] * (n + 1)
            visited[1] = True
            while queue:
                u = queue.popleft()
                for v in graph[u]:
                    if not visited[v]:
                        visited[v] = True
                        queue.append(v)
                    if dp[u] < float('inf'):
                        if dp[v] == 0:
                            dp[v] = dp[u]
                        elif dp[v] == dp[u]:
                            dp[v] = float('inf')
                    else:
                        dp[v] = float('inf')
            result = []
            for i in range(1, n + 1):
                if dp[i] == 0:
                    result.append(0)
                elif dp[i] == 1:
                    result.append(1)
                elif dp[i] == float('inf'):
                    result.append(-1)
                else:
                    result.append(2)
            results.append(" ".join(map(str, result)))
    print("\n".join(results))

main()
